with j as (select * from jsonb_to_recordset($law7d0045$[{"code_id":"KoAP_RF","article_number":"8.2","version_date":"2001-12-30","article_text":"влечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей; на должностных лиц - от десяти тысяч до тридцати тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от тридцати тысяч до пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от ста тысяч до двухсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток. (В редакции  Федерального закона от 14.07.2022 № 287-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от тридцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до семидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двухсот пятидесяти тысяч до четырехсот тысяч рублей или административное приостановление деятельности на срок до девяноста суток. (В редакции  Федерального закона от 14.07.2022 № 287-ФЗ)\n\nвлекут наложение административного штрафа на граждан в размере от пяти тысяч до семи тысяч рублей; на должностных лиц - от сорока тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от семидесяти тысяч до восьмидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от четырехсот тысяч до пятисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток. (В редакции  Федерального закона от 14.07.2022 № 287-ФЗ)\n\nвлекут наложение административного штрафа на граждан в размере от десяти тысяч до пятнадцати тысяч рублей; на должностных лиц - от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n(Дополнение частью - Федеральный закон от 14.07.2022 № 287-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от двадцати тысяч до тридцати тысяч рублей; на должностных лиц - от сорока тысяч до шестидесяти тысяч рублей с конфискацией транспортного средства, являющегося орудием совершения административного правонарушения, или без таковой; на юридических лиц - от шестидесяти тысяч до ста тысяч рублей с конфискацией транспортного средства, являющегося орудием совершения административного правонарушения, или без таковой.\n\n(Дополнение частью - Федеральный закон от 14.07.2022 № 287-ФЗ)\n\nвлекут наложение административного штрафа на граждан в размере от сорока тысяч до пятидесяти тысяч рублей; на должностных лиц - от шестидесяти тысяч до восьмидесяти тысяч рублей; на юридических лиц - от ста тысяч до ста двадцати тысяч рублей.\n\n(Дополнение частью - Федеральный закон от 14.07.2022 № 287-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от шестидесяти тысяч до семидесяти тысяч рублей; на должностных лиц - от восьмидесяти тысяч до ста тысяч рублей с конфискацией грузовых транспортных средств, прицепов к ним, тракторов и других самоходных машин, являющихся орудиями совершения административного правонарушения, или без таковой; на юридических лиц - от ста пятидесяти тысяч до двухсот тысяч рублей с конфискацией грузовых транспортных средств, прицепов к ним, тракторов и других самоходных машин, являющихся орудиями совершения административного правонарушения, или без таковой.\n\n(Дополнение частью - Федеральный закон от 14.07.2022 № 287-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от трехсот тысяч до четырехсот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до шести тысяч рублей; на должностных лиц - от сорока тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до шестидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятисот тысяч до шестисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\nвлекут наложение административного штрафа на граждан в размере от шести тысяч до семи тысяч рублей; на должностных лиц - от пятидесяти тысяч до шестидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от шестидесяти тысяч до семидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от шестисот тысяч до семисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\n10. Неисполнение обязанности по ведению учета в области обращения с отходами производства и потребления -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\n11. Неисполнение обязанности по проведению мониторинга состояния и загрязнения окружающей среды на территориях объектов размещения отходов производства и потребления и в пределах их воздействия на окружающую среду -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования ю\n\nридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\n12. Неисполнение обязанности по проведению инвентаризации объектов размещения отходов производства и потребления -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до шестидесяти тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот пятидесяти тысяч рублей.\n\n13. Нарушение сроков или периодичности размещения информации в федеральной государственной информационной системе учета твердых коммунальных отходов либо размещение в указанной системе недостоверной информации или информации не в полном объеме, за исключением случаев, предусмотренных частью 14 настоящей статьи, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до шести тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до семидесяти тысяч рублей; на юридических лиц - от семидесяти тысяч до ста пятидесяти тысяч рублей.\n\n(Дополнение частью - Федеральный закон от 25.12.2023 № 668-ФЗ)\n\n14. Нарушение должностным лицом федерального органа исполнительной власти, органа исполнительной власти субъекта Российской Федерации, органа местного самоуправления сроков или периодичности размещения информации в федеральной государственной информационной системе учета твердых коммунальных отходов либо размещение в указанной системе недостоверной информации или информации не в полном объеме -\n\nвлечет наложение административного штрафа в размере от пяти тысяч до десяти тысяч рублей.\n\n(Дополнение частью - Федеральный закон от 25.12.2023 № 668-ФЗ)\n\n(Статья в редакции Федерального закона от 17.06.2019 № 141-ФЗ)","article_title":"Статья 8.2. Несоблюдение требований в области охраны окружающей среды при обращении с отходами производства и потребления","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"99a3cc8fc60b16b36f4e8ac5486790eaf2b21bd838fad87113a732ca2d064f94"},{"code_id":"KoAP_RF","article_number":"8.21","version_date":"2001-12-30","article_text":"1. Несоблюдение требований в области охраны окружающей среды при обращении с веществами, разрушающими озоновый слой, -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч рублей; на должностных лиц - от десяти тысяч до тридцати тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от тридцати тысяч до пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от ста тысяч до двухсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n2. Повторное в течение года совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч пятисот до трех тысяч пятисот рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до семидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двухсот пятидесяти тысяч до четырехсот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение статьей - Федеральный закон от 17.06.2019 № 141-ФЗ)","article_title":"Статья 8.21. Несоблюдение требований в области охраны окружающей среды при обращении с веществами, разрушающими озоновый слой","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b2b3240a9d3b48f37f1f085b5add1c4a592889e0b6866404ffdfd17322eab83d"},{"code_id":"KoAP_RF","article_number":"8.22","version_date":"2001-12-30","article_text":"1. Несоблюдение требований в области охраны окружающей среды при производстве, обращении или обезвреживании потенциально опасных химических веществ, в том числе радиоактивных, иных веществ и микроорганизмов -\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до десяти тысяч рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от семидесяти тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от ста тысяч до двухсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n2. Повторное в течение года совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от десяти тысяч до двенадцати тысяч рублей; на должностных лиц - от пятидесяти тысяч до шестидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от ста тысяч до ста двадцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двухсот пятидесяти тысяч до трехсот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n3. Действия (бездействие), предусмотренные частью 1 настоящей статьи, повлекшие причинение вреда здоровью людей или окружающей среде либо возникновение эпидемии или эпизоотии, если эти действия (бездействие) не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от пятнадцати тысяч до двадцати тысяч рублей; на должностных лиц - от шестидесяти тысяч до семидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от ста двадцати тысяч до ста сорока тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от трехсот пятидесяти тысяч до четырехсот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение статьей - Федеральный закон от 17.06.2019 № 141-ФЗ)","article_title":"Статья 8.22. Несоблюдение требований в области охраны окружающей среды при производстве, обращении или обезвреживании потенциально опасных химических веществ, в том числе радиоактивных, иных веществ и микроорганизмов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f04cf885447747304c696e2544f888a6afe880a147539cb961534a7c6ebcf2d"},{"code_id":"KoAP_RF","article_number":"8.23","version_date":"2001-12-30","article_text":"1. Несоблюдение требований в области охраны окружающей среды при сборе, накоплении, транспортировании, обработке, утилизации или обезвреживании отходов животноводства -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей; на должностных лиц - от тридцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до шестидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двухсот пятидесяти тысяч до трехсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n2. Повторное в течение года совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до четырех тысяч рублей; на должностных лиц - от сорока тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от шестидесяти тысяч до семидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от трехсот пятидесяти тысяч до четырехсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n3. Действия (бездействие), предусмотренные частью 1 настоящей статьи, повлекшие причинение вреда здоровью людей или окружающей среде либо возникновение эпидемии или эпизоотии, если эти действия (бездействие) не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от четырех тысяч до пяти тысяч рублей; на должностных лиц - от пятидесяти тысяч до шестидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от восьмидесяти тысяч до девяноста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятисот тысяч до шестисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n4. Несоблюдение требований в области охраны окружающей среды при размещении отходов животноводства -\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до семи тысяч рублей; на должностных лиц - от сорока тысяч до шестидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от шестидесяти тысяч до восьмидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятисот тысяч до семисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n5. Повторное в течение года совершение административного правонарушения, предусмотренного частью 4 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от семи тысяч до восьми тысяч рублей; на должностных лиц - от шестидесяти тысяч до семидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от восьмидесяти тысяч до девяноста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от семисот тысяч до восьмисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n6. Действия (бездействие), предусмотренные частью 4 настоящей статьи, повлекшие причинение вреда здоровью людей или окружающей среде либо возникновение эпидемии или эпизоотии, если эти действия (бездействие) не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от восьми тысяч до девяти тысяч рублей; на должностных лиц - от семидесяти тысяч до восьмидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от девяноста тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от восьмисот тысяч до девятисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение статьей - Федеральный закон от 17.06.2019 № 141-ФЗ)","article_title":"Статья 8.23. Несоблюдение требований в области охраны окружающей среды при обращении с отходами животноводства","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"98fe3e4cdb70b650466c572dc3cc01a11586fc876aed2f79f40ec3ec1d0dfa1e"},{"code_id":"KoAP_RF","article_number":"8.3","version_date":"2001-12-30","article_text":"Нарушение правил испытаний, производства, транспортировки, хранения, применения и иного обращения с пестицидами и агрохимикатами (за исключением случаев, когда такие правила содержатся в технических регламентах), которое может повлечь причинение вреда окружающей среде, -   (В редакции федеральных законов от 30.12.2008 № 309-ФЗ; от 18.07.2011 № 237-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч рублей; на должностных лиц - от двух тысяч до пяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от двух тысяч до пяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от десяти тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток.  (В редакции федеральных законов от 26.12.2005 № 183-ФЗ; от 22.06.2007 № 116-ФЗ)","article_title":"Статья 8.3. Нарушение правил обращения с пестицидами и агрохимикатами","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a993ccb929bdc2d1a32638fbbd1ab98ebf575ddbc531c9e720afcd0662ef9d8c"},{"code_id":"KoAP_RF","article_number":"8.4","version_date":"2001-12-30","article_text":"1. Невыполнение требований законодательства об обязательности проведения государственной экологической экспертизы, финансирование или реализация проектов, программ и иной документации, подлежащих государственной экологической экспертизе и не получивших положительного заключения государственной экологической экспертизы, -\n\nвлечет предупреждение или наложение административного штрафа на граждан в размере от одной тысячи пятисот до двух тысяч рублей; на должностных лиц - от десяти тысяч до двадцати тысяч рублей; на юридических лиц - от ста тысяч до двухсот пятидесяти тысяч рублей. (В редакции федеральных законов от 26.12.2005 № 183-ФЗ, от 22.06.2007 № 116-ФЗ, от 27.07.2010 № 239-ФЗ, от 17.06.2019 № 141-ФЗ)\n\n2. Осуществление деятельности, не соответствующей документации, которая получила положительное заключение государственной экологической экспертизы, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до двух тысяч пятисот рублей; на должностных лиц - от десяти тысяч до двадцати тысяч рублей; на юридических лиц - от ста тысяч до двухсот пятидесяти тысяч рублей.  (В редакции федеральных законов от 26.12.2005 № 183-ФЗ, от 22.06.2007 № 116-ФЗ, от 17.06.2019 № 141-ФЗ)\n\n3. Незаконный отказ в государственной регистрации заявлений о проведении общественной экологической экспертизы -\n\nвлечет наложение административного штрафа на должностных лиц от пяти тысяч до десяти тысяч рублей.  (В редакции федеральных законов от 26.12.2005 № 183-ФЗ; от 22.06.2007 № 116-ФЗ)","article_title":"Статья 8.4. Нарушение законодательства об экологической экспертизе","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"78f1e0ac3a286892b4dea923d1240e064e14a274ae39ab6dd75348fb0ac33af8"},{"code_id":"KoAP_RF","article_number":"8.5","version_date":"2001-12-30","article_text":"1. Сокрытие, умышленное искажение или несвоевременное сообщение полной и достоверной информации о состоянии окружающей среды и природных ресурсов, об источниках загрязнения окружающей среды и природных ресурсов или иного вредного воздействия на окружающую среду и природные ресурсы, о радиационной обстановке, данных, полученных при осуществлении производственного экологического контроля, либо информации, содержащейся в заявлении о постановке на государственный учет объектов, оказывающих негативное воздействие на окружающую среду, или декларации о воздействии на окружающую среду, декларации о плате за негативное воздействие на окружающую среду, отчете о выполнении плана мероприятий по охране окружающей среды или программы повышения экологической эффективности, а равно искажение сведений о состоянии земель, водных объектов и других объектов окружающей среды лицами, обязанными сообщать такую информацию в соответствии с законодательством Российской Федерации, за исключением случаев, предусмотренных частями 13 и 14 статьи 8.2, статьями 8.52 и 8.53, частями 3 и 4 статьи 8.50, статьей 8.51 настоящего Кодекса, -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до трех тысяч рублей; на должностных лиц - от десяти тысяч до тридцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до двухсот тысяч рублей.\n\n2. Повторное совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей или дисквалификацию на срок от одного года до трех лет; на юридических лиц - от двухсот тысяч до трехсот тысяч рублей.\n\n(Статья в редакции Федерального закона от 08.08.2024 № 242-ФЗ)","article_title":"Статья 8.5. Сокрытие или искажение экологической информации","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a2042f7c9983a990b73094301c1161c6a52852a44d703f82be9419c6da26e081"},{"code_id":"KoAP_RF","article_number":"8.51","version_date":"2001-12-30","article_text":"1. Непредставление или несвоевременное представление отчетности о выполнении нормативов утилизации отходов от использования товаров или деклараций о количестве выпущенных в обращение на территории Российской Федерации товаров, упаковки товаров, включенных в перечень товаров, упаковки товаров, подлежащих утилизации после утраты ими потребительских свойств, реализованных для внутреннего потребления на территории Российской Федерации за предыдущий календарный год, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до шести тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до семидесяти тысяч рублей; на юридических лиц - от семидесяти тысяч до ста пятидесяти тысяч рублей.\n\n2. Представление отчетности о выполнении нормативов утилизации отходов от использования товаров или деклараций о количестве выпущенных в обращение на территории Российской Федерации товаров, упаковки товаров, включенных в перечень товаров, упаковки товаров, подлежащих утилизации после утраты ими потребительских свойств, реализованных для внутреннего потребления на территории Российской Федерации за предыдущий календарный год, в неполном объеме либо отчетности, содержащей недостоверные сведения, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до шести тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - в двукратном размере суммы сбора по каждой группе товаров, группе упаковки товаров, подлежащего уплате производителями товаров, импортерами товаров, которые не обеспечивают самостоятельную утилизацию отходов от использования товаров, но не менее ста тысяч рублей; на юридических лиц - в двукратном размере суммы сбора по каждой группе товаров, группе упаковки товаров, подлежащего уплате производителями товаров, импортерами товаров, которые не обеспечивают самостоятельную утилизацию отходов от использования товаров, но не менее двухсот пятидесяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 17.06.2019 № 141-ФЗ)","article_title":"Статья 8.51. Нарушение порядка представления отчетности о выполнении нормативов утилизации отходов от использования товаров или деклараций о количестве выпущенных в обращение на территории Российской Федерации товаров, упаковки товаров, включенных в перечень товаров, упаковки товаров, подлежащих утилизации после утраты ими потребительских свойств, реализованных для внутреннего потребления на территории Российской Федерации за предыдущий календарный год","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c9cd93e01f951527225900a6f636a0f7be6b48afd9bad3c4a60ee7f3af219b19"},{"code_id":"KoAP_RF","article_number":"8.52","version_date":"2001-12-30","article_text":"1. Ненаправление в установленный законом срок утвержденного акта лесопатологического обследования в уполномоченный федеральный орган исполнительной власти -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до двадцати тысяч рублей.\n\n2. Включение недостоверных сведений о санитарном и лесопатологическом состоянии лесов в акт лесопатологического обследования либо размещение на официальном сайте органа государственной власти или органа местного самоуправления в информационно-телекоммуникационной сети \"Интернет\" утвержденного акта лесопатологического обследования, содержащего недостоверные сведения о санитарном и лесопатологическом состоянии лесов, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до двадцати тысяч рублей.\n\n3. Совершение административных правонарушений, предусмотренных частями 1 и 2 настоящей статьи, в отношении защитных лесов, особо защитных участков лесов, а также лесов, расположенных в лесопарковых зеленых поясах, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 06.06.2019 № 135-ФЗ)","article_title":"Статья 8.52. Сокрытие сведений о санитарном и лесопатологическом состоянии лесов или включение недостоверных сведений о санитарном и лесопатологическом состоянии лесов в акт лесопатологического обследования","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2eee2abea7903df304c7eceb0aa230a8d77495eb4ae65d38ae786e1376a3364c"},{"code_id":"KoAP_RF","article_number":"8.53","version_date":"2001-12-30","article_text":"Непредставление или несвоевременное представление информации для включения в федеральную государственную информационную систему учета и контроля за обращением с отходами I и II классов опасности, либо ее неразмещение или несвоевременное размещение в указанной системе, либо нарушение порядка представления такой информации, либо представление или размещение ее не в полном объеме, либо представление или размещение недостоверной информации -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч","article_title":"Статья 8.53. Нарушение порядка представления информации в федеральную государственную информационную систему учета и контроля за обращением с отходами I и II классов опасности либо порядка ее размещения в данной системе","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77a9b802c79e4ec6eb613fdc6fa563bf6b22c7e91d17b7ee2164579686151c00"},{"code_id":"KONST_RF","article_number":"1","version_date":"1993-12-12","article_text":"1.Российская Федерация — Россия есть демократическое федеративное правовое государство с республиканской формой правления.\n\n2.Наименования Российская Федерация и Россия равнозначны.","article_title":"Статья 1","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8c7380fd1d1fc0812fdee122ac9347237daeb46c97277e5f828d39bf327ac72"},{"code_id":"KONST_RF","article_number":"10","version_date":"1993-12-12","article_text":"Государственная власть в Российской Федерации осуществляется на основе разделения на законодательную, исполнительную и судебную. Органы законодательной, исполнительной и судебной власти самостоятельны.","article_title":"Статья 10","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"84c2b73a00a867db117cb9c24547d76c49a203bb1ac159cab59b8968a0f0e337"},{"code_id":"KONST_RF","article_number":"100","version_date":"1993-12-12","article_text":"1.Совет Федерации и Государственная Дума заседают раздельно.\n\n2.Заседания Совета Федерации и Государственной Думы являются открытыми. В случаях, предусмотренных регламентом палаты, она вправе проводить закрытые заседания.\n\n3.Палаты могут собираться совместно для заслушивания посланий Президента Российской Федерации.*","article_title":"Статья 100","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11262768ce5f164ac50a53a5be1b800594f3cc881788412443d4dc0c8d0cd07a"},{"code_id":"KONST_RF","article_number":"101","version_date":"1993-12-12","article_text":"1.Совет Федерации избирает из своего состава Председателя Совета Федерации и его заместителей. Государственная Дума избирает из своего состава Председателя Государственной Думы и его заместителей.\n\n2.Председатель Совета Федерации и его заместители, Председатель Государственной Думы и его заместители ведут заседания и ведают внутренним распорядком палаты.\n\n3.Совет Федерации и Государственная Дума образуют комитеты и комиссии, проводят по вопросам своего ведения парламентские слушания.\n\n4.Каждая из палат принимает свой регламент и решает вопросы внутреннего распорядка своей деятельности.\n\n5.Для осуществления контроля за исполнением федерального бюджета Совет Федерации и Государственная Дума образуют Счетную палату, состав и порядок деятельности которой определяются федеральным законом.","article_title":"Статья 101","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dcfcb1e693d7450aec58fcc6f4a616dde26a5254de3d7cadfb0fd470de559a62"},{"code_id":"KONST_RF","article_number":"102","version_date":"1993-12-12","article_text":"1.К ведению Совета Федерации относятся:\n\nа)утверждение изменения границ между субъектами Российской Федерации;\n\nб)утверждение указа Президента Российской Федерации о введении военного положения;\n\nв)утверждение указа Президента Российской Федерации о введении чрезвычайного положения;\n\nг)решение вопроса о возможности использования Вооруженных Сил Российской Федерации за пределами территории Российской Федерации;\n\nд)назначение выборов Президента Российской Федерации;\n\nе)отрешение Президента Российской Федерации от должности; лишение неприкосновенности Президента Российской Федерации, прекратившего исполнение своих полномочий;*\n\nж)назначение на должность по представлению Президента Российской Федерации Председателя Конституционного Суда Российской Федерации, заместителя Председателя Конституционного Суда Российской Федерации и судей Конституционного Суда Российской Федерации, Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации и судей Верховного Суда Российской Федерации;*\n\nз)проведение консультаций по предложенным Президентом Российской Федерации кандидатурам на должность Генерального прокурора Российской Федерации, заместителей Генерального прокурора Российской Федерации, прокуроров субъектов Российской Федерации, прокуроров военных и других специализированных прокуратур, приравненных к прокурорам субъектов Российской Федерации;*\n\nи)назначение на должность и освобождение от должности Председателя Счетной палаты и половины от общего числа аудиторов Счетной палаты по представлению Президента Российской Федерации;*\n\nк)проведение консультаций по предложенным Президентом Российской Федерации кандидатурам на должность руководителей федеральных органов исполнительной власти (включая федеральных министров), ведающих вопросами обороны, безопасности государства, внутренних дел, юстиции, иностранных дел, предотвращения чрезвычайных ситуаций и ликвидации последствий стихийных бедствий, общественной безопасности;*\n\nл)прекращение по представлению Президента Российской Федерации в соответствии с федеральным конституционным законом полномочий Председателя Конституционного Суда Российской Федерации, заместителя Председателя Конституционного Суда Российской Федерации и судей Конституционного Суда Российской Федерации, Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации и судей Верховного Суда Российской Федерации, председателей, заместителей председателей и судей кассационных и апелляционных судов в случае совершения ими поступка, порочащего честь и достоинство судьи, а также в иных предусмотренных федеральным конституционным законом случаях, свидетельствующих о невозможности осуществления судьей своих полномочий;*\n\nм)заслушивание ежегодных докладов Генерального прокурора Российской Федерации о состоянии законности и правопорядка в Российской Федерации;*\n\n2.Совет Федерации принимает постановления по вопросам, отнесенным к его ведению Конституцией Российской Федерации.\n\n3.Постановления Совета Федерации принимаются большинством голосов от общего числа сенаторов Российской Федерации, если иной порядок принятия решений не предусмотрен Конституцией Российской Федерации.*","article_title":"Статья 102","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25941e4070546a9ff0b3d368047b880048eae5bd0aa2c852a204be909eec2754"},{"code_id":"KONST_RF","article_number":"103","version_date":"1993-12-12","article_text":"1.К ведению Государственной Думы относятся:\n\nа)утверждение по представлению Президента Российской Федерации кандидатуры Председателя Правительства Российской Федерации;*\n\nа1)утверждение по представлению Председателя Правительства Российской Федерации кандидатур заместителей Председателя Правительства Российской Федерации и федеральных министров, за исключением федеральных министров, указанных в пункте «д1» статьи 83 Конституции Российской Федерации;*\n\nб)решение вопроса о доверии Правительству Российской Федерации;\n\nв)заслушивание ежегодных отчетов Правительства Российской Федерации о результатах его деятельности, в том числепо вопросам, поставленным Государственной Думой;\n\nЧасть 1 дополнена новым пунктом«в», буквенные обозначения последующих пунктов изменены в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 30 декабря 2008 г. № 7-ФКЗ«О контрольных полномочиях Государственной Думы в отношении Правительства Российской Федерации», вступившим в силу со дня его официального опубликования 31 декабря 2008 г.(Российская газета, 2008, 31 декабря).\n\nг)назначение на должность и освобождение от должности Председателя Центрального банка Российской Федерации;\n\nг1)заслушивание ежегодных отчетов Центрального банка Российской Федерации;*\n\nд)назначение на должность и освобождение от должности заместителя Председателя Счетной палаты и половины от общего числа аудиторов Счетной палаты по представлению Президента Российской Федерации;*\n\nе)назначение на должность и освобождение от должности Уполномоченного по правам человека, действующего в соответствии с федеральным конституционным законом. Уполномоченным по правам человека может быть гражданин Российской Федерации, постоянно проживающий в Российской Федерации, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Уполномоченному по правам человека в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации;*\n\nж)объявление амнистии;\n\nз)выдвижение обвинения против Президента Российской Федерации в целях отрешения его от должности или против Президента Российской Федерации, прекратившего исполнение своих полномочий, в целях лишения его неприкосновенности.*\n\n2.Государственная Дума принимает постановления по вопросам, отнесенным к ее ведению Конституцией Российской Федерации.\n\n3.Постановления Государственной Думы принимаются большинством голосов от общего числа депутатов Государственной Думы, если иной порядок принятия решений не предусмотрен Конституцией Российской Федерации.","article_title":"Статья 103","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fbdc2463f42db62867ebcaa41646d2ddd01ea6377f075759ff7e3e56abd301bf"},{"code_id":"KONST_RF","article_number":"104","version_date":"1993-12-12","article_text":"1.Право законодательной инициативы принадлежит Президенту Российской Федерации, Совету Федерации, сенаторам Российской Федерации, депутатам Государственной Думы, Правительству Российской Федерации, законодательным (представительным) органам субъектов Российской Федерации. Право законодательной инициативы принадлежит также Конституционному Суду Российской Федерации и Верховному Суду Российской Федерации по вопросам их ведения.*\n\n2.Законопроекты вносятся в Государственную Думу.\n\n3.Законопроекты о введении или отмене налогов, освобождении от их уплаты, о выпуске государственных займов, об изменении финансовых обязательств государства, другие законопроекты, предусматривающие расходы, покрываемые за счет федерального бюджета, могут быть внесены только при наличии заключения Правительства Российской Федерации.","article_title":"Статья 104","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd96abb0e4b833367c8db4238d89a5a7785ace6c570dfb46d8c3732e19a91d01"},{"code_id":"KONST_RF","article_number":"105","version_date":"1993-12-12","article_text":"1.Федеральные законы принимаются Государственной Думой.\n\n2.Федеральные законы принимаются большинством голосов от общего числа депутатов Государственной Думы, если иное не предусмотрено Конституцией Российской Федерации.\n\n3.Принятые Государственной Думой федеральные законы в течение пяти дней передаются на рассмотрение Совета Федерации.\n\n4.Федеральный закон считается одобренным Советом Федерации, если за него проголосовало более половины от общего числа членов этой палаты либо если в течение четырнадцати дней он не был рассмотрен Советом Федерации. В случае отклонения федерального закона Советом Федерации палаты могут создать согласительную комиссию для преодоления возникших разногласий, после чего федеральный закон подлежит повторному рассмотрению Государственной Думой.\n\n5.В случае несогласия Государственной Думы с решением Совета Федерации федеральный закон считается принятым, если при повторном голосовании за него проголосовало не менее двух третей от общего числа депутатов Государственной Думы.","article_title":"Статья 105","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ae752ec4a6077be5caa66f8a589a48315ad4ea68110f48cf0eb1cd997f84c225"},{"code_id":"KONST_RF","article_number":"106","version_date":"1993-12-12","article_text":"Обязательному рассмотрению в Совете Федерации подлежат принятые Государственной Думой федеральные законы по вопросам:\n\nа)федерального бюджета;\n\nб)федеральных налогов и сборов;\n\nв)финансового, валютного, кредитного, таможенного регулирования, денежной эмиссии;\n\nг)ратификации и денонсации международных договоров Российской Федерации;\n\nд)статуса и защиты государственной границы Российской Федерации;\n\nе)войны и мира.","article_title":"Статья 106","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"16d09d42d121c4b0ba004e66213d9bd279f727691064118c3bb8178951e36729"},{"code_id":"KONST_RF","article_number":"107","version_date":"1993-12-12","article_text":"1.Принятый федеральный закон в течение пяти дней направляется Президенту Российской Федерации для подписания и обнародования.\n\n2.Президент Российской Федерации в течение четырнадцати дней подписывает федеральный закон и обнародует его.\n\n3.Если Президент Российской Федерации в течение четырнадцати дней с момента поступления федерального закона отклонит его, то Государственная Дума и Совет Федерации в установленном Конституцией Российской Федерации порядке вновь рассматривают данный закон. Если при повторном рассмотрении федеральный закон будет одобрен в ранее принятой редакции большинством не менее двух третей голосов от общего числа сенаторов Российской Федерации и депутатов Государственной Думы, он подлежит подписанию Президентом Российской Федерации в течение семи дней и обнародованию. Если Президент Российской Федерации в течение указанного срока обратится в Конституционный Суд Российской Федерации с запросом о проверке конституционности федерального закона, срок для подписания такого закона приостанавливается на время рассмотрения запроса Конституционным Судом Российской Федерации. Если Конституционный Суд Российской Федерации подтвердит конституционность федерального закона, Президент Российской Федерации подписывает его в трехдневный срок с момента вынесения Конституционным Судом Российской Федерации соответствующего решения. Если Конституционный Суд Российской Федерации не подтвердит конституционности федерального закона, Президент Российской Федерации возвращает его в Государственную Думу без подписания.*","article_title":"Статья 107","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9fe37ed9e8756a6ef7f3b709139df6d86f9cacd83ce2004f2f04bde050bc7aad"},{"code_id":"KONST_RF","article_number":"108","version_date":"1993-12-12","article_text":"1.Федеральные конституционные законы принимаются по вопросам, предусмотренным Конституцией Российской Федерации.\n\n2.Федеральный конституционный закон считается принятым, если он одобрен большинством не менее трех четвертей голосов от общего числа сенаторов Российской Федерации и не менее двух третей голосов от общего числа депутатов Государственной Думы. Принятый федеральный конституционный закон в течение четырнадцати дней подлежит подписанию Президентом Российской Федерации и обнародованию. Если Президент Российской Федерации в течение указанного срока обратится в Конституционный Суд Российской Федерации с запросом о проверке конституционности федерального конституционного закона, срок для подписания такого закона приостанавливается на время рассмотрения запроса Конституционным Судом Российской Федерации. Если Конституционный Суд Российской Федерации подтвердит конституционность федерального конституционного закона, Президент Российской Федерации подписывает его в трехдневный срок с момента вынесения Конституционным Судом Российской Федерации соответствующего решения. Если Конституционный Суд Российской Федерации не подтвердит конституционности федерального конституционного закона, Президент Российской Федерации возвращает его в Государственную Думу без подписания.*","article_title":"Статья 108","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c6bbba00b7807cb81b41773e9743719de3d67aba85455c4b23e4aa8cb733cd89"},{"code_id":"KONST_RF","article_number":"109","version_date":"1993-12-12","article_text":"1.Государственная Дума может быть распущена Президентом Российской Федерации в случаях, предусмотренных статьями 111, 112 и 117 Конституции Российской Федерации.*\n\n2.В случае роспуска Государственной Думы Президент Российской Федерации назначает дату выборов с тем, чтобы вновь избранная Государственная Дума собралась не позднее чем через четыре месяца с момента роспуска.\n\n3.Государственная Дума не может быть распущена по основаниям, предусмотренным статьей 117 Конституции Российской Федерации, в течение года после ее избрания.\n\n4.Государственная Дума не может быть распущена с момента выдвижения ею обвинения против Президента Российской Федерации до принятия соответствующего решения Советом Федерации.\n\n5.Государственная Дума не может быть распущена в период действия на всей территории Российской Федерации военного или чрезвычайного положения, а также в течение шести месяцев до окончания срока полномочий Президента Российской Федерации.","article_title":"Статья 109","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2624671090fbb08d409de2d1fe60eb939e934c137946114c479241c46049e7c2"},{"code_id":"KONST_RF","article_number":"11","version_date":"1993-12-12","article_text":"1.Государственную власть в Российской Федерации осуществляют Президент Российской Федерации, Федеральное Собрание(Совет Федерации и Государственная Дума), Правительство Российской Федерации, суды Российской Федерации.\n\n2.Государственную власть в субъектах Российской Федерации осуществляют образуемые ими органы государственной власти.\n\n3.Разграничение предметов ведения и полномочий между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации осуществляется настоящей Конституцией, Федеративным и иными договорами о разграничении предметов ведения и полномочий.","article_title":"Статья 11","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6898bd265c2cb5358dc8c1481d0b71b1b5193cc43f162a0a99b66a07fb074531"},{"code_id":"KONST_RF","article_number":"110","version_date":"1993-12-12","article_text":"1.Исполнительную власть Российской Федерации осуществляет Правительство Российской Федерации под общим руководством Президента Российской Федерации.*\n\n2.Правительство Российской Федерации состоит из Председателя Правительства Российской Федерации, заместителей Председателя Правительства Российской Федерации и федеральных министров.\n\n3.Правительство Российской Федерации руководит деятельностью федеральных органов исполнительной власти, за исключением федеральных органов исполнительной власти, руководство деятельностью которых осуществляет Президент Российской Федерации.*\n\n4.Председателем Правительства Российской Федерации, Заместителем Председателя Правительства Российской Федерации, федеральным министром, иным руководителем федерального органа исполнительной власти может быть гражданин Российской Федерации, достигший 30 лет, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Председателю Правительства Российской Федерации, заместителям Председателя Правительства Российской Федерации, федеральным министрам, иным руководителям федеральных органов исполнительной власти в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.*","article_title":"Статья 110","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"abee031891374b3265dbb3f33eb26e42bdcee00cf222b34b8c54d5a5aab8cf0f"},{"code_id":"KONST_RF","article_number":"111","version_date":"1993-12-12","article_text":"1.Председатель Правительства Российской Федерации назначается Президентом Российской Федерации после утверждения его кандидатуры Государственной Думой.*\n\n2.Представление по кандидатуре Председателя Правительства Российской Федерации вносится в Государственную Думу Президентом Российской Федерации не позднее двухнедельного срока после вступления в должность вновь избранного Президента Российской Федерации или после отставки Правительства Российской Федерации либо в течение недели со дня отклонения кандидатуры Председателя Правительства Российской Федерации Государственной Думой или освобождения Президентом Российской Федерации от должности либо отставки Председателя Правительства Российской Федерации.*\n\n3.Государственная Дума рассматривает представленную Президентом Российской Федерации кандидатуру Председателя Правительства Российской Федерации в течение недели со дня внесения представления.*\n\n4.После трехкратного отклонения представленных кандидатур Председателя Правительства Российской Федерации Государственной Думой Президент Российской Федерации назначает Председателя Правительства Российской Федерации. В этом случае Президент Российской Федерации вправе распустить Государственную Думу и назначить новые выборы.*","article_title":"Статья 111","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8af5de5dd127d5469c5142a288ef35d7e5febedbc34820b1862ea5de08a59faa"},{"code_id":"KONST_RF","article_number":"112","version_date":"1993-12-12","article_text":"1.Председатель Правительства Российской Федерации не позднее недельного срока после назначения представляет Президенту Российской Федерации предложения о структуре федеральных органов исполнительной власти, за исключением случая, когда предшествующий Председатель Правительства Российской Федерации освобожден от должности Президентом Российской Федерации.\n\n2.Председатель Правительства Российской Федерации представляет Государственной Думе на утверждение кандидатуры заместителей Председателя Правительства Российской Федерации и федеральных министров (за исключением федеральных министров, указанных в пункте «д1» статьи 83 Конституции Российской Федерации). Государственная Дума не позднее недельного срока принимает решение по представленным кандидатурам.\n\n3.Заместители Председателя Правительства Российской Федерации и федеральные министры, кандидатуры которых утверждены Государственной Думой, назначаются на должность Президентом Российской Федерации. Президент Российской Федерации не вправе отказать в назначении на должность заместителей Председателя Правительства Российской Федерации и федеральных министров, кандидатуры которых утверждены Государственной Думой.\n\n4.После трехкратного отклонения Государственной Думой представленных в соответствии с частью 2 настоящей статьи кандидатур заместителей Председателя Правительства Российской Федерации, федеральных министров Президент Российской Федерации вправе назначить заместителей Председателя Правительства Российской Федерации, федеральных министров из числа кандидатур, представленных Председателем Правительства Российской Федерации. Если после трехкратного отклонения Государственной Думой представленных в соответствии с частью 2 настоящей статьи кандидатур более одной трети должностей членов Правительства Российской Федерации (за исключением должностей федеральных министров, указанных в пункте «д1» статьи 83 Конституции Российской Федерации) остаются вакантными, Президент Российской Федерации вправе распустить Государственную Думу и назначить новые выборы.\n\n5.В случае, предусмотренном частью 4 статьи 111 Конституции Российской Федерации, а также в случае роспуска Государственной Думы в соответствии с Конституцией Российской Федерации Президент Российской Федерации назначает заместителей Председателя Правительства Российской Федерации, федеральных министров (за исключением федеральных министров, указанных в пункте «д1» статьи 83 Конституции Российской Федерации) по представлению Председателя Правительства Российской Федерации.","article_title":"Статья 112","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e5160448394fb1d3ae5075fb0ad2cb2c19222f840b083ee66d5e67c9943bb3de"},{"code_id":"KONST_RF","article_number":"113","version_date":"1993-12-12","article_text":"Председатель Правительства Российской Федерации в соответствии с Конституцией Российской Федерации, федеральными законами, указами, распоряжениями, поручениями Президента Российской Федерации организует работу Правительства Российской Федерации. Председатель Правительства Российской Федерации несет персональную ответственность перед Президентом Российской Федерации за осуществление возложенных на Правительство Российской Федерации полномочий.","article_title":"Статья 113","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"00d4c7c95f004ebc0f05d268f8f7919ec49b3794e06fb368e137e588a2d94e65"},{"code_id":"KONST_RF","article_number":"114","version_date":"1993-12-12","article_text":"1.Правительство Российской Федерации:\n\nа)разрабатывает и представляет Государственной Думе федеральный бюджет и обеспечивает его исполнение; представляет Государственной Думе отчет об исполнении федерального бюджета; представляет Государственной Думе ежегодные отчеты о результатах своей деятельности, в том числепо вопросам, поставленным Государственной Думой;\n\nРедакция пункта«а» части 1 приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 30 декабря 2008 г. № 7-ФКЗ«О контрольных полномочиях Государственной Думы в отношении Правительства Российской Федерации», вступившим в силу со дня его официального опубликования 31 декабря 2008 г.(Российская газета, 2008, 31 декабря).\n\nб)обеспечивает проведение в Российской Федерации единой финансовой, кредитной и денежной политики;\n\nв)обеспечивает проведение в Российской Федерации единой социально ориентированной государственной политики в области культуры, науки, образования, здравоохранения, социального обеспечения, поддержки, укрепления и защиты семьи, сохранения традиционных семейных ценностей, а также в области охраны окружающей среды;*\n\nв1)обеспечивает государственную поддержку научно-технологического развития Российской Федерации, сохранение и развитие ее научного потенциала;*\n\nв2)обеспечивает функционирование системы социальной защиты инвалидов, основанной на полном и равном осуществлении ими прав и свобод человека и гражданина, их социальную интеграцию без какой-либо дискриминации, создание доступной среды для инвалидов и улучшение качества их жизни;*\n\nг)осуществляет управление федеральной собственностью;\n\nд)осуществляет меры по обеспечению обороны страны, государственной безопасности, реализации внешней политики Российской Федерации;\n\nе)осуществляет меры по обеспечению законности, прав и свобод граждан, охране собственности и общественного порядка, борьбе с преступностью;\n\nе1)осуществляет меры по поддержке институтов гражданского общества, в том числе некоммерческих организаций, обеспечивает их участие в выработке и проведении государственной политики;*\n\nе2)осуществляет меры по поддержке добровольческой (волонтерской) деятельности;*\n\nе3)содействует развитию предпринимательства и частной инициативы;*\n\nе4)обеспечивает реализацию принципов социального партнерства в сфере регулирования трудовых и иных непосредственно связанных с ними отношений;*\n\nе5)осуществляет меры, направленные на создание благоприятных условий жизнедеятельности населения, снижение негативного воздействия хозяйственной и иной деятельности на окружающую среду, сохранение уникального природного и биологического многообразия страны, формирование в обществе ответственного отношения к животным;*\n\nе6)создает условия для развития системы экологического образования граждан, воспитания экологической культуры;*\n\nж)осуществляет иные полномочия, возложенные на него Конституцией Российской Федерации, федеральными законами, указами Президента Российской Федерации.\n\n2.Порядок деятельности Правительства Российской Федерации определяется федеральным конституционным законом.","article_title":"Статья 114","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"10cb3ab24b52ec7289c775b8e20dabe5f38926bc0f84f185410d9dbf354d89c2"},{"code_id":"KONST_RF","article_number":"115","version_date":"1993-12-12","article_text":"1.На основании и во исполнение Конституции Российской Федерации, федеральных законов, указов, распоряжений, поручений Президента Российской Федерации Правительство Российской Федерации издает постановления и распоряжения, обеспечивает их исполнение.*\n\n2.Постановления и распоряжения Правительства Российской Федерации обязательны к исполнению в Российской Федерации.\n\n3.Постановления и распоряжения Правительства Российской Федерации в случае их противоречия Конституции Российской Федерации, федеральным законам, указам и распоряжениям Президента Российской Федерации могут быть отменены Президентом Российской Федерации.*","article_title":"Статья 115","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a4a90f4a6dc66ec4f1c7488aea716887ecd5f30a50c401ea4876a194c6194872"},{"code_id":"KONST_RF","article_number":"116","version_date":"1993-12-12","article_text":"Перед вновь избранным Президентом Российской Федерации Правительство Российской Федерации слагает свои полномочия.","article_title":"Статья 116","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"028e7808e14a8b68813e05b9501ed456b0701b4631b1c1bc7a10331c62e7df62"},{"code_id":"KONST_RF","article_number":"117","version_date":"1993-12-12","article_text":"1.Правительство Российской Федерации может подать в отставку, которая принимается или отклоняется Президентом Российской Федерации.\n\n2.Президент Российской Федерации может принять решение об отставке Правительства Российской Федерации.\n\n3.Государственная Дума может выразить недоверие Правительству Российской Федерации. Постановление о недоверии Правительству Российской Федерации принимается большинством голосов от общего числа депутатов Государственной Думы. После выражения Государственной Думой недоверия Правительству Российской Федерации Президент Российской Федерации вправе объявить об отставке Правительства Российской Федерации либо не согласиться с решением Государственной Думы. В случае если Государственная Дума в течение трех месяцев повторно выразит недоверие Правительству Российской Федерации, Президент Российской Федерации объявляет об отставке Правительства Российской Федерации либо распускает Государственную Думу и назначает новые выборы.*\n\n4.Председатель Правительства Российской Федерации вправе поставить перед Государственной Думой вопрос о доверии Правительству Российской Федерации, который подлежит рассмотрению в течение семи дней. Если Государственная Дума отказывает в доверии Правительству Российской Федерации, Президент Российской Федерации в течение семи дней вправе принять решение об отставке Правительства Российской Федерации или о роспуске Государственной Думы и назначении новых выборов. В случае если Правительство Российской Федерации в течение трех месяцев повторно поставит перед Государственной Думой вопрос о доверии, а Государственная Дума в доверии Правительству Российской Федерации откажет, Президент Российской Федерации принимает решение об отставке Правительства Российской Федерации или о роспуске Государственной Думы и назначении новых выборов.*\n\n41.Председатель Правительства Российской Федерации, Заместитель Председателя Правительства Российской Федерации, федеральный министр вправе подать в отставку, которая принимается или отклоняется Президентом Российской Федерации.*\n\n5.В случае отставки или сложения полномочий Правительство Российской Федерации по поручению Президента Российской Федерации продолжает действовать до сформирования нового Правительства Российской Федерации. В случае освобождения от должности Президентом Российской Федерации или отставки Председателя Правительства Российской Федерации, Заместителя Председателя Правительства Российской Федерации, федерального министра Президент Российской Федерации вправе поручить этому лицу продолжать исполнять обязанности по должности или возложить их исполнение на другое лицо до соответствующего назначения.*\n\n6.Государственная Дума не может выразить недоверие Правительству Российской Федерации, а Председатель Правительства Российской Федерации не может ставить перед Государственной Думой вопрос о доверии Правительству Российской Федерации в случаях, предусмотренных частями 3 — 5 статьи 109 Конституции Российской Федерации, а также в течение года после назначения Председателя Правительства Российской Федерации в соответствии с частью 4 статьи 111 Конституции Российской Федерации.*\n\nРедакция наименования главы  7 приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 5 февраля 2014 г. № 2-ФКЗ «О Верховном Суде Российской Федерации и прокуратуре Российской Федерации», вступившим в силу со дня его официального опубликования 6 февраля 2014 г. (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2014, 6 февраля, № 0001201402060001).","article_title":"Статья 117","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1c6794a3280d65dfc0a7ff4eafe53bee5e9df540b2127e81f4861ce3f3f8c63"},{"code_id":"KONST_RF","article_number":"118","version_date":"1993-12-12","article_text":"1.Правосудие в Российской Федерации осуществляется только судом.\n\n2.Судебная власть осуществляется посредством конституционного, гражданского, арбитражного, административного и уголовного судопроизводства.*\n\n3.Судебная система Российской Федерации устанавливается Конституцией Российской Федерации и федеральным конституционным законом. Судебную систему Российской Федерации составляют Конституционный Суд Российской Федерации, Верховный Суд Российской Федерации, федеральные суды общей юрисдикции, арбитражные суды, мировые судьи субъектов Российской Федерации. Создание чрезвычайных судов не допускается.*","article_title":"Статья 118","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"113236f307f6b7d26fce398162e5db9bfa83fde44a5b6e11d532f0fefe112f7d"},{"code_id":"KONST_RF","article_number":"119","version_date":"1993-12-12","article_text":"Судьями могут быть граждане Российской Федерации, достигшие 25 лет, имеющие высшее юридическое образование и стаж работы по юридической профессии не менее пяти лет, постоянно проживающие в Российской Федерации, не имеющие гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Судьям судов Российской Федерации в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации. Федеральным законом могут быть установлены дополнительные требования к судьям судов Российской Федерации.","article_title":"Статья 119","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"042b71a7d9d9fa18aa84383ea92e192dbef3989bd5bbe07805d853cd0c1377d6"},{"code_id":"KONST_RF","article_number":"12","version_date":"1993-12-12","article_text":"В Российской Федерации признается и гарантируется местное самоуправление. Местное самоуправление в пределах своих полномочий самостоятельно. Органы местного самоуправления не входят в систему органов государственной власти.","article_title":"Статья 12","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"97f395e79a69ff62a7cda29c3b6c4ad8c27b9e006eff4f26c58ec99ddbef5f82"},{"code_id":"KONST_RF","article_number":"120","version_date":"1993-12-12","article_text":"1.Судьи независимы и подчиняются только Конституции Российской Федерации и федеральному закону.\n\n2.Суд, установив при рассмотрении дела несоответствие акта государственного или иного органа закону, принимает решение в соответствии с законом.","article_title":"Статья 120","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3b6b1d6fc5ba0c7b089d193825f3f50ec10829177059b406aaa4aef359e01d89"},{"code_id":"KONST_RF","article_number":"121","version_date":"1993-12-12","article_text":"1.Судьи несменяемы.\n\n2.Полномочия судьи могут быть прекращены или приостановлены не иначе как в порядке и по основаниям, установленным федеральным законом.","article_title":"Статья 121","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ce0f1e34cbe2a4cc561bc6ec9c1cf6badc9c0a3cfbfcc9bcc14a397768ecc598"},{"code_id":"KONST_RF","article_number":"122","version_date":"1993-12-12","article_text":"1.Судьи неприкосновенны.\n\n2.Судья не может быть привлечен к уголовной ответственности иначе как в порядке, определяемом федеральным законом.","article_title":"Статья 122","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2439e4d8fcf6f420df14a130b635d71fed60a3e1d05bf113ea102fc4ba3167c"},{"code_id":"KONST_RF","article_number":"123","version_date":"1993-12-12","article_text":"1.Разбирательство дел во всех судах открытое. Слушание дела в закрытом заседании допускается в случаях, предусмотренных федеральным законом.\n\n2.Заочное разбирательство уголовных дел в судах не допускается, кроме случаев, предусмотренных федеральным законом.\n\n3.Судопроизводство осуществляется на основе состязательности и равноправия сторон.\n\n4.В случаях, предусмотренных федеральным законом, судопроизводство осуществляется с участием присяжных заседателей.","article_title":"Статья 123","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"006f6edcd3ecf06109c8d2cd065d693adb0452afa41c213638909d5550730d17"},{"code_id":"KONST_RF","article_number":"124","version_date":"1993-12-12","article_text":"Финансирование судов производится только из федерального бюджета и должно обеспечивать возможность полного и независимого осуществления правосудия в соответствии с федеральным законом.","article_title":"Статья 124","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f3250b62ff12d62e77a706ec2a2c48017e0df9e609b61987ed46e5f1facf544b"}]$law7d0045$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
